# -*- coding: utf-8 -*-
"""База для оператора: вердикт + причины (от частой к редкой), у каждой «как проверить» и «как исправить».
Ключ — заголовок проверенного разбора (t из kb_verified*). Оператор чинит сам: указываем точные пути в Mission Planner (MP)
и значения параметров. Условия/пороги — из проверенных разборов (kb_verified*), сверенных с кодом Copter-4.6.3.

OPS[t] = dict(v=вердикт, title=короткий заголовок, what=что это значит, causes=[(причина, как проверить, как исправить), ...])
вердикты: block — взлёт заблокирован; land — сажай дрон; warn — будь внимателен; info — можно не обращать внимания.
"""

OPS = {}

# ---- пути в Mission Planner
P_PARAMS = "MP → Config → Full Parameter List"
P_COMPASS = "MP → Setup → Mandatory Hardware → Compass"
P_ACCEL = "MP → Setup → Mandatory Hardware → Accel Calibration"
P_RADIO = "MP → Setup → Mandatory Hardware → Radio Calibration"
P_FRAME = "MP → Setup → Mandatory Hardware → Frame Type"
P_SERVO = "MP → Setup → Mandatory Hardware → Servo Output"
P_FS = "MP → Setup → Mandatory Hardware → FailSafe"
P_BATT = "MP → Setup → Optional Hardware → Battery Monitor"
P_STATUS = "MP → Data → вкладка Status"
P_MSG = "MP → Data → вкладка Messages"
P_LOG = "MP → Data → DataFlash Logs → Review a Log"
SAVE = "нажми Write Params и перезагрузи дрон (выключи питание и включи)"
REB = "Выключи питание дрона полностью и включи снова."


def O(t, v, title, what, causes):
    OPS[t] = dict(v=v, title=title, what=what, causes=[dict(c=c, chk=chk, fix=fix) for c, chk, fix in causes])


def PAR(name, good, why=""):
    """причина «неверный параметр»: как проверить и как исправить в Full Parameter List"""
    return ("Неверное значение " + name + (" — " + why if why else ""),
            P_PARAMS + " → в поиске набери " + name + " и посмотри значение.",
            "Поставь " + name + " = " + good + ", " + SAVE + ".")


